/// One JSON-RPC method of the unified MCP gateway.
struct McpMethodSpec {
    std::string_view id;
    std::string_view rpc;
    /// Empty when the method is not a tool call.
    std::optional<std::string_view> tool;
    std::string_view description;
};

inline constexpr std::array<McpMethodSpec, 6> MCP_METHODS{{
    McpMethodSpec{
        .id = "initialize",
        .rpc = "initialize",
        .tool = std::nullopt,
        .description = "Open an MCP session and fetch server capabilities and instructions.",
    },
    McpMethodSpec{
        .id = "ping",
        .rpc = "ping",
        .tool = std::nullopt,
        .description = "Check gateway liveness over JSON-RPC.",
    },
    McpMethodSpec{
        .id = "list_tools",
        .rpc = "tools/list",
        .tool = std::nullopt,
        .description = "List the fixed ten-verb Tempera capability-fabric surface; product cards never appear as flat product tool names.",
    },
    McpMethodSpec{
        .id = "call_tool",
        .rpc = "tools/call",
        .tool = std::nullopt,
        .description = "Call a fixed fabric verb. Discover product cards with tempera_search, inspect a card with tempera_describe, then invoke its opaque capability reference through tempera_invoke or tempera_prepare/tempera_commit.",
    },
    McpMethodSpec{
        .id = "whoami",
        .rpc = "tools/call",
        .tool = "tempera_whoami",
        .description = "Fetch the caller's identity, workspace, and scopes as seen by the gateway.",
    },
    McpMethodSpec{
        .id = "status",
        .rpc = "tools/call",
        .tool = "tempera_status",
        .description = "Fetch gateway upstream health for every connected product MCP server.",
    },
}};

/// MCP gateway JSON-RPC error codes.
inline constexpr std::int64_t MCP_ERROR_PLAN_LIMIT = -32002;
inline constexpr std::int64_t MCP_ERROR_INVALID_REQUEST = -32600;
inline constexpr std::int64_t MCP_ERROR_METHOD_NOT_FOUND = -32601;
inline constexpr std::int64_t MCP_ERROR_INVALID_PARAMS = -32602;
inline constexpr std::int64_t MCP_ERROR_INTERNAL = -32603;

/// Look up one operation by product key and snake_case operation id.
constexpr const OperationSpec *find_operation(std::string_view product,
                                             std::string_view id) noexcept {
    for (const OperationSpec &op : OPERATIONS) {
        if (op.product == product && op.id == id) {
            return &op;
        }
    }
    return nullptr;
}

/// Look up one product by snake_case key.
constexpr const ProductSpec *find_product(std::string_view key) noexcept {
    for (const ProductSpec &product : PRODUCTS) {
        if (product.key == key) {
            return &product;
        }
    }
    return nullptr;
}

